host_operator_src="""
#include "conv3d_min_softmax_custom_tiling.h"
#include "register/op_def_registry.h"
#include "tiling/tiling_api.h"

namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM  = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    Conv3dMinSoftmaxCustomTilingData tiling;

    // 输入总元素数（示例）
    uint32_t totalLength = context->GetInputShape(0)->GetOriginShape().GetShapeSize();
    context->SetBlockDim(BLOCK_DIM);
    tiling.set_totalLength(totalLength);
    tiling.set_tileNum(TILE_NUM);

    // 从输入形状推导SoftMax的M、K（示例性写法，真实项目应解析形状）
    // 假定输入为N,C,D,H,W，softmax沿C做（K=C），min沿D做，输出为N,C,H,W。
    // 为了生成SoftMax tiling，这里构造shape [M, K]，M=N*H*W，K=C。
    // 若无法直接从接口取维度，下面给出保守示例值，请在真实项目中替换为实际计算。
    std::vector<int64_t> inDims = context->GetInputShape(0)->GetOriginShape().GetDims();
    uint32_t M = 1;
    uint32_t K = 1;
    if (inDims.size() == 5) {
        // N,C,D,H,W
        uint64_t N = static_cast<uint64_t>(inDims[0]);
        uint64_t C = static_cast<uint64_t>(inDims[1]);
        uint64_t H = static_cast<uint64_t>(inDims[3]);
        uint64_t W = static_cast<uint64_t>(inDims[4]);
        uint64_t m64 = N * H * W;
        M = static_cast<uint32_t>(m64);
        K = static_cast<uint32_t>(C);
    }
    tiling.set_mDim(M);
    tiling.set_kDim(K);

    // 获取SoftMax最小临时空间并生成SoftMax tiling
    // SoftMax形状为[M, K]
    std::vector<int64_t> smShapeVec = {static_cast<int64_t>(M), static_cast<int64_t>(K)};
    ge::Shape smShape(smShapeVec);
    uint32_t localWorkSpaceSize = AscendC::GetSoftMaxMinTmpSize(smShape, sizeof(float), false);
    tiling.set_tmpBufSize(localWorkSpaceSize);
    AscendC::SoftMaxTilingFunc(smShape, sizeof(float), localWorkSpaceSize, tiling.softmaxTilingData);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // 无需workspace
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}

} // namespace optiling

namespace ge {

// 形状推理：输入为(N, C, D, H, W)，输出为(N, C, H, W)。
// 若输入维度不为5，则回退为与输入相同形状（示例）。
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);
    std::vector<int64_t> inDims = x_shape->GetStorageShape().GetDims();
    std::vector<int64_t> outDims;
    if (inDims.size() == 5) {
        outDims = {inDims[0], inDims[1], inDims[3], inDims[4]};
    } else {
        outDims = inDims;
    }
    gert::Shape* y_shape = context->GetOutputShape(0);
    y_shape->SetDimNum(outDims.size());
    for (size_t i = 0; i < outDims.size(); ++i) {
        y_shape->SetDim(i, outDims[i]);
    }
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}

} // namespace ge

